using Avalonia;
using Avalonia.Controls;
using Avalonia.Layout;
using Avalonia.Media;
using Avalonia.Threading;
namespace WirePulse;
public sealed class SettingsWindow:Window {
 Settings settings;readonly Settings global;readonly StackPanel content=new(){Spacing=15};readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap};readonly MediaService media;readonly Spectrum spectrum;readonly Func<string> audio;readonly DispatcherTimer timer;
 public SettingsWindow(Settings settings,Spectrum spectrum,MediaService media,Func<string> audio,Dictionary<string,Settings> displays){global=settings;this.settings=settings;this.spectrum=spectrum;this.media=media;this.audio=audio;Title="WirePulse · Ajustes";Width=780;Height=700;MinWidth=600;MinHeight=450;Icon=new WindowIcon(Path.Combine(AppContext.BaseDirectory,"Assets","WirePulse.png"));var root=new DockPanel{Margin=new Thickness(20)};var groups=new ComboBox{ItemsSource=new[]{"Audio","Fondo","Orbe","Espectro","Tarjeta","Rendimiento"},SelectedIndex=0,HorizontalAlignment=HorizontalAlignment.Stretch,Margin=new Thickness(0,0,0,15)};DockPanel.SetDock(groups,Dock.Top);root.Children.Add(groups);var displaysPanel=new StackPanel{Spacing=8,Margin=new Thickness(0,0,0,15)};var mode=new CheckBox{Content="Ajustar cada pantalla de forma independiente",IsChecked=global.IndependentDisplays};var selector=new ComboBox{ItemsSource=new[]{"Todas las pantallas"}.Concat(displays.Keys).ToArray(),SelectedIndex=0,HorizontalAlignment=HorizontalAlignment.Stretch};displaysPanel.Children.Add(mode);displaysPanel.Children.Add(selector);DockPanel.SetDock(displaysPanel,Dock.Top);root.Children.Add(displaysPanel);mode.IsCheckedChanged+=(_,_)=>{global.IndependentDisplays=mode.IsChecked==true;global.Save();selector.SelectedIndex=global.IndependentDisplays&&displays.Count>0?1:0;};selector.SelectionChanged+=(_,_)=>{this.settings=global.IndependentDisplays&&selector.SelectedItem is string key&&displays.TryGetValue(key,out var selected)?selected:global;ShowGroup((string)groups.SelectedItem!);};if(global.IndependentDisplays&&displays.Count>0)selector.SelectedIndex=1;var reset=new Button{Content="Restablecer diseño",Margin=new Thickness(0,15,0,0)};DockPanel.SetDock(reset,Dock.Bottom);reset.Click+=(_,_)=>{this.settings.Reset();ShowGroup((string)groups.SelectedItem!);};root.Children.Add(reset);root.Children.Add(new ScrollViewer{Content=content,HorizontalScrollBarVisibility=Avalonia.Controls.Primitives.ScrollBarVisibility.Disabled});Content=root;groups.SelectionChanged+=(_,_)=>ShowGroup((string)groups.SelectedItem!);ShowGroup("Audio");timer=new DispatcherTimer(TimeSpan.FromSeconds(1),DispatcherPriority.Background,(_,_)=>Refresh());timer.Start();Closed+=(_,_)=>timer.Stop();}
 void Refresh(){var s=spectrum.Snapshot();status.Text=$"{audio()}\n64 bandas · {s.SampleRate:N0} Hz · FFT {s.FftSize} · {s.SampleRate/(double)s.FftSize:F2} Hz/bin\n{media.Status}";}
 void Label(string text)=>content.Children.Add(new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap});
 void Toggle(string label,bool value,Action<bool> change){var check=new CheckBox{Content=label,IsChecked=value};check.IsCheckedChanged+=(_,_)=>change(check.IsChecked==true);content.Children.Add(check);}
 void Input(string label,string value,Action<string> change,bool secret=false){Label(label);var box=new TextBox{Text=value,PasswordChar=secret?'●':'\0'};box.LostFocus+=(_,_)=>change(box.Text??"");content.Children.Add(box);}
 void ShowGroup(string group){content.Children.Clear();if(group=="Audio"){Refresh();content.Children.Add(status);Label("Captura la salida del sistema en memoria. No usa el micrófono ni guarda audio. El espectro cubre desde DC hasta Nyquist; la resolución depende del muestreo real de salida.");}
 if(group=="Tarjeta"){Label("Proveedor de música");var choice=new ComboBox{ItemsSource=new[]{"Automático","Apple Music","Spotify","Cider"},SelectedItem=global.MediaSource,HorizontalAlignment=HorizontalAlignment.Stretch};choice.SelectionChanged+=(_,_)=>{global.MediaSource=choice.SelectedItem?.ToString()??"Automático";global.Save();};content.Children.Add(choice);Toggle("Tarjeta arriba centrada",settings.TopCentered,b=>{settings.TopCentered=b;settings.Save();});Input("Margen superior (%)",settings.TopMargin.ToString(System.Globalization.CultureInfo.InvariantCulture),s=>{if(double.TryParse(s,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var n)){settings.TopMargin=Math.Clamp(n,0,80);settings.Save();}});Label("Cider: activa su API local y crea un token de Playback en Ajustes → Connectivity. Si publica los controles multimedia del sistema, se detecta también sin API.");Input("Dirección local de Cider",global.CiderUrl,s=>{if(Uri.TryCreate(s,UriKind.Absolute,out var u)&&u.IsLoopback&&u.Scheme=="http"){if(s!=global.CiderUrl)global.CiderToken="";global.CiderUrl=s;global.Save();}});Input("Token de Cider",global.CiderToken,s=>{global.CiderToken=s;global.Save();},true);}
 foreach(var spec in settings.Specs.Where(x=>x.Group==group)){if(spec.Kind=="toggle")Toggle(spec.Title,settings.On(spec.Key),b=>settings.Set(spec.Key,b));else if(spec.Kind=="slider"){var caption=new TextBlock{Text=$"{spec.Title}: {settings.N(spec.Key):0.###}"};content.Children.Add(caption);var slider=new Slider{Minimum=spec.Min,Maximum=spec.Max,Value=settings.N(spec.Key),TickFrequency=spec.Step,IsSnapToTickEnabled=true};slider.PropertyChanged+=(_,e)=>{if(e.Property==Slider.ValueProperty){var n=slider.Value;caption.Text=$"{spec.Title}: {n:0.###}";settings.Set(spec.Key,n);}};content.Children.Add(slider);}else Input(spec.Title,settings.Text(spec.Key),s=>{if(spec.Kind=="color"&&!Color.TryParse(s,out _))return;settings.Set(spec.Key,s);});}
 if(group=="Rendimiento")Toggle("Pausar animación",settings.Paused,b=>settings.Paused=b);}
}
